H.background();
const w = H.W, h = H.H;
const m = Math.max(0.1, P.m), deg = H.clamp(P.deg, 0, 60), g = 9.8;
const th = deg * Math.PI / 180;
const N = m * g * Math.cos(th);            // normal force on an incline
const Wt = m * g;                          // weight
// Incline: hinge at lower-left, rises to the right.
const ox = w * 0.20, oy = h * 0.78;        // pivot (bottom of slope)
const L = Math.min(w * 0.62, (h * 0.6) / Math.max(0.05, Math.sin(th) + 0.0001 + 0.5));
const ex = ox + L * Math.cos(th), ey = oy - L * Math.sin(th);
// ground + incline surface
H.line(ox - 30, oy, ex + 40, oy, { color: H.colors.axis, width: 2 });
H.path([[ox, oy], [ex, ey], [ex, oy]], { color: H.colors.grid, width: 2, fill: "rgba(124,196,255,0.10)", close: true });
// block slides up/down the ramp, looping (kinematic, just for life)
const s = (0.5 + 0.35 * Math.sin(t)) * L * 0.7;   // distance along ramp, bounded
const bx = ox + (s) * Math.cos(th), by = oy - (s) * Math.sin(th);
// Unit vectors in SCREEN coords (y points down). The ramp surface rises to the
// right, so the up-ramp direction is (cos th, -sin th). The OUTWARD surface
// normal (pointing away from the solid wedge, which lies below-right) is the
// up-and-LEFT perpendicular: screen vector (-sin th, -cos th).
const ux = Math.cos(th), uy = -Math.sin(th);
const nx = -Math.sin(th), ny = Math.cos(th);   // outward normal: arrow uses (nx, -ny) -> up-left
const bs = 26;
// block centered slightly off the surface along the outward normal
const cx = bx + nx * bs * 0.7, cy = by - ny * bs * 0.7;
H.rect(cx - bs / 2, cy - bs / 2, bs, bs, { fill: H.colors.accent2, stroke: H.colors.bg, width: 2, radius: 4 });
// weight arrow: straight down, scaled
const wLen = H.clamp(Wt * 0.5, 14, 130);
H.arrow(cx, cy, cx, cy + wLen, { color: H.colors.warn, width: 3.5 });
H.text("W = mg = " + Wt.toFixed(0) + " N", cx + 8, cy + wLen + 4, { color: H.colors.warn, size: 12 });
// normal arrow: perpendicular to surface (outward, up-left), scaled
const nLen = H.clamp(N * 0.5, 10, 130);
H.arrow(cx, cy, cx + nx * nLen, cy - ny * nLen, { color: H.colors.good, width: 3.5 });
H.text("N", cx + nx * nLen - 12, cy - ny * nLen - 4, { color: H.colors.good, size: 13, weight: 700 });
H.text("Normal force:  N = m·g·cos(theta)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("N is perpendicular to the surface; flat ground (θ=0) → N = mg", 24, 52, { color: H.colors.sub, size: 12 });
H.text("m = " + m.toFixed(1) + " kg   θ = " + deg.toFixed(0) + "°   N = " + N.toFixed(1) + " N   (W = " + Wt.toFixed(1) + " N)", 24, 74, { color: H.colors.sub, size: 13 });
H.legend([{ label: "weight W", color: H.colors.warn }, { label: "normal N", color: H.colors.good }], H.W - 160, 28);
